namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and communication." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds 3 patents in natural language processing.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Mathematics", Bio = "Dr. Martinez focuses on applied mathematics and statistics. He has 15 years of teaching experience and previously worked in quantitative finance.", Email = "rmartinez@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of English", Bio = "Dr. Johnson is an award-winning author and literary critic specializing in contemporary American fiction and creative writing.", Email = "sjohnson@university.edu" },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Professor of Physics", Bio = "Dr. Wilson conducts research in quantum mechanics and particle physics. He was part of the team that confirmed the Higgs boson discovery.", Email = "jwilson@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Park", Title = "Associate Professor of History", Bio = "Dr. Park specializes in East Asian history and digital humanities. She leads the university's digital archives initiative.", Email = "epark@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Assistant Professor of Computer Science", Bio = "Dr. Brown researches distributed systems and cloud computing. He previously worked as a senior engineer at a major tech company.", Email = "mbrown@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of essential data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:00–11:50 AM", DepartmentId = 1, InstructorId = 6, IsFeatured = true },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction management, and introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, InstructorId = 6 },
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and computer graphics.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 6, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 7, Code = "ENG 101", Title = "College Writing", Description = "Develop clear, effective writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, InstructorId = 3 },
            new() { Id = 8, Code = "ENG 220", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present day, examining themes of identity, freedom, and social change.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 9, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:50 PM", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "PHYS 201", Title = "Modern Physics", Description = "Special relativity, quantum mechanics, atomic structure, and nuclear physics.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 11, Code = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from ancient times to 1500 CE, covering political, cultural, and economic developments.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", DepartmentId = 5, InstructorId = 5, IsFeatured = true },
            new() { Id = 12, Code = "HIST 250", Title = "Modern East Asia", Description = "History of China, Japan, and Korea from the 19th century to the present, focusing on modernization, war, and globalization.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 5, InstructorId = 5 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

